.sl-testimonial-carousel {
    padding: clamp(3rem, 6vw, 6rem) clamp(1rem, 4vw, 2rem);
    width: 100%;
    background-color: var(--smartlearn-bg);
    font-family: var(--smartlearn-body-font, system-ui, sans-serif);
}

.sl-testimonial-carousel .sl-container {
    max-width: 900px;
    margin: 0 auto;
    position: relative;
}

.sl-testimonial-carousel .sl-sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.sl-testimonial-carousel .sl-section-title {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: clamp(1.75rem, 3vw, 2.25rem);
    font-weight: 700;
    color: var(--smartlearn-text);
    text-align: center;
    margin-bottom: 2.5rem;
}

.sl-testimonial-carousel .sl-carousel-track {
    display: grid;
    touch-action: pan-y;
}

.sl-testimonial-carousel .sl-slide {
    grid-area: 1 / 1;
    margin: 0;
    opacity: 0;
    transition: opacity 0.5s ease;
    pointer-events: none;
    display: flex;
    align-items: center;
    justify-content: center;
}

.sl-testimonial-carousel .sl-slide.active {
    opacity: 1;
    pointer-events: auto;
    z-index: 2;
}

.sl-testimonial-carousel .sl-content {
    text-align: center;
    background: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.1));
    padding: 4rem;
    border-radius: var(--smartlearn-radius, 16px);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    width: 100%;
}

.sl-testimonial-carousel .sl-quote-icon {
    width: 40px;
    height: 40px;
    color: var(--smartlearn-primary);
    opacity: 0.6;
    margin-bottom: 2rem;
}

.sl-testimonial-carousel .sl-blockquote {
    margin: 0;
}

.sl-testimonial-carousel .sl-quote-text {
    font-size: clamp(1.25rem, 3vw, 2rem);
    font-weight: 600;
    color: var(--smartlearn-text);
    line-height: 1.4;
    margin-bottom: 3rem;
}

@media (max-width: 768px) {
    .sl-testimonial-carousel .sl-content {
        padding: 2rem;
    }
}

.sl-testimonial-carousel .sl-author {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 1rem;
}

.sl-testimonial-carousel .sl-avatar {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    object-fit: cover;
    object-position: center top;
    flex-shrink: 0;
}

.sl-testimonial-carousel .sl-name {
    font-weight: 700;
    color: var(--smartlearn-text);
    font-size: 1.125rem;
    text-align: start;
}

.sl-testimonial-carousel .sl-role {
    color: var(--smartlearn-text-muted);
    font-size: 0.875rem;
    text-align: start;
}

.sl-testimonial-carousel .sl-controls {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 1rem;
    margin-top: 2rem;
}

.sl-testimonial-carousel .sl-ctrl-btn {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: transparent;
    border: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.2));
    color: var(--smartlearn-text);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background-color 0.25s ease, border-color 0.25s ease, color 0.25s ease;
}

.sl-testimonial-carousel .sl-ctrl-btn:hover {
    background: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg));
    border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg));
    color: var(--smartlearn-btn-text, #ffffff);
}

.sl-testimonial-carousel .sl-ctrl-btn:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}

[dir="rtl"] .sl-testimonial-carousel .sl-ctrl-btn svg {
    transform: scaleX(-1);
}

.sl-testimonial-carousel .sl-dots {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.sl-testimonial-carousel .sl-dot {
    width: 12px;
    height: 12px;
    padding: 0;
    border-radius: 50%;
    border: 2px solid var(--smartlearn-text-muted);
    background: transparent;
    cursor: pointer;
    transition: background-color 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
}

.sl-testimonial-carousel .sl-dot[aria-current="true"] {
    background-color: var(--smartlearn-primary);
    border-color: var(--smartlearn-primary);
    transform: scale(1.15);
}

.sl-testimonial-carousel .sl-dot:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
    .sl-testimonial-carousel .sl-slide,
    .sl-testimonial-carousel .sl-ctrl-btn,
    .sl-testimonial-carousel .sl-dot {
        transition: none;
    }
}

