(function() {
    function initCarousel(section) {
        if (!section || section.dataset.slInit === '1') return;
        section.dataset.slInit = '1';

        var slides = Array.prototype.slice.call(section.querySelectorAll('.sl-slide'));
        var dots = Array.prototype.slice.call(section.querySelectorAll('.sl-dot'));
        var nextBtn = section.querySelector('.sl-next');
        var prevBtn = section.querySelector('.sl-prev');
        var track = section.querySelector('.sl-carousel-track');
        var statusEl = section.querySelector('.sl-carousel-status');
        if (!slides.length || !nextBtn || !prevBtn) return;

        var currentIndex = 0;
        var touchStartX = 0;

        function updateCarousel(announce) {
            slides.forEach(function(s, idx) {
                var isActive = idx === currentIndex;
                s.classList.toggle('active', isActive);
                if (isActive) {
                    s.removeAttribute('aria-hidden');
                    s.removeAttribute('inert');
                } else {
                    s.setAttribute('aria-hidden', 'true');
                    s.setAttribute('inert', '');
                }
            });
            dots.forEach(function(d, idx) {
                d.setAttribute('aria-current', idx === currentIndex ? 'true' : 'false');
            });
            if (announce && statusEl) {
                statusEl.textContent = 'Testimonial ' + (currentIndex + 1) + ' of ' + slides.length;
            }
        }

        function goNext() {
            currentIndex = (currentIndex + 1) % slides.length;
            updateCarousel(true);
        }

        function goPrev() {
            currentIndex = (currentIndex - 1 + slides.length) % slides.length;
            updateCarousel(true);
        }

        nextBtn.addEventListener('click', goNext);
        prevBtn.addEventListener('click', goPrev);

        dots.forEach(function(dot, idx) {
            dot.addEventListener('click', function() {
                currentIndex = idx;
                updateCarousel(true);
            });
        });

        section.addEventListener('keydown', function(e) {
            if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
            if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.isContentEditable)) return;
            var isRtl = getComputedStyle(section).direction === 'rtl';
            if (e.key === 'ArrowRight') {
                if (isRtl) goPrev(); else goNext();
            } else {
                if (isRtl) goNext(); else goPrev();
            }
        });

        if (track) {
            track.addEventListener('touchstart', function(e) {
                if (e.changedTouches && e.changedTouches.length) {
                    touchStartX = e.changedTouches[0].clientX;
                }
            }, { passive: true });

            track.addEventListener('touchend', function(e) {
                if (!e.changedTouches || !e.changedTouches.length) return;
                var dx = e.changedTouches[0].clientX - touchStartX;
                if (Math.abs(dx) < 40) return;
                var isRtl = getComputedStyle(section).direction === 'rtl';
                if (dx < 0) {
                    if (isRtl) goPrev(); else goNext();
                } else {
                    if (isRtl) goNext(); else goPrev();
                }
            }, { passive: true });
        }

        updateCarousel(false);
    }

    function initAll() {
        document.querySelectorAll('.sl-testimonial-carousel').forEach(initCarousel);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();
